import React from "react";
import Svg, {
  G,
  Path,
  Defs,
  LinearGradient,
  ClipPath,
  Stop,
  Rect,
  Circle,
  Line,
} from "react-native-svg";

interface IconProps {
  width?: string | number;
  height?: string | number;
  fill?: string;
}

interface IconsWrapperProps extends IconProps {
  children: JSX.Element | JSX.Element[];
}

const primary = "#0777FF";

/**
 * This is a wrapper for icons with default props
 * to avoid code duplicacy
 * @important 24*24 default value
 * @param width
 * @param height
 * @param children
 * @param fill when deconstructing remember that sometimes
 * the fill needs to be applied to path instead of Svg
 * @param viewBox
 * @returns Jsx.element
 */
export const IconsWrapper = ({
  width = 24,
  height = 24,
  children,
  fill,
}: IconsWrapperProps) => (
  <Svg width={width} height={height} fill={fill} viewBox="0 0 24 24">
    {children}
  </Svg>
);

